# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"
require "webmock/rspec"

RSpec.describe "Timekeeping relay test hooks" do
  # Anyone able to pause the relay could stop every company's entries from
  # reaching the monolith, so the hook takes the same service token as the
  # other internal routes.
  it "refuses the relay pause and resume hooks without the service token" do
    service_token = "service-#{SecureRandom.hex(24)}"
    refused = [401, { "reason" => "unauthorized" }]
    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => service_token
    ) do
      user_token = mint_token({ sub: 7, company_id: 1, role: "owner" })

      # A refused pause must leave a running relay running.
      Timekeeping::TestHooks.resume_relay!
      expect(Timekeeping::TestHooks.relay_paused?).to be(false)

      post "/internal/v1/test-hooks/relay/pause"
      expect([response.status, response.parsed_body]).to eq(refused)

      post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer #{user_token}" }
      expect([response.status, response.parsed_body]).to eq(refused)

      post "/internal/v1/test-hooks/relay/pause", headers: { "Authorization" => "Bearer not-the-service-token" }
      expect([response.status, response.parsed_body]).to eq(refused)
      expect(Timekeeping::TestHooks.relay_paused?).to be(false)

      # A refused resume must leave a paused relay paused.
      Timekeeping::TestHooks.pause_relay!
      expect(Timekeeping::TestHooks.relay_paused?).to be(true)

      post "/internal/v1/test-hooks/relay/resume", headers: { "Authorization" => "Bearer #{service_token}x" }
      expect([response.status, response.parsed_body]).to eq(refused)

      post "/internal/v1/test-hooks/relay/resume"
      expect([response.status, response.parsed_body]).to eq(refused)
      expect(Timekeeping::TestHooks.relay_paused?).to be(true)
    end
  ensure
    Timekeeping::TestHooks.resume_relay!
  end

  it "a relay paused through the hook sends nothing until resumed, then delivers the waiting row" do
    hook_service_token = "service-#{SecureRandom.hex(24)}"
    auth = { "Authorization" => "Bearer #{hook_service_token}" }
    delivery = WebMock.stub_request(:post, "http://snapshots.test/internal/v1/timekeeping/entry-snapshots")
      .to_return(status: 200, headers: { "Content-Type" => "application/json" },
                 body: JSON.generate(applied: 1, ignored: 0))
    position = insert_outbox_rows(outbox_row(id: 501)).first

    with_timekeeping_env(
      Timekeeping::Environment::TOKEN_PUBLIC_KEY => rsa_key_pair.public_key.to_pem,
      Timekeeping::Environment::SERVICE_TOKEN => hook_service_token,
      Timekeeping::Environment::MONOLITH_SNAPSHOT_URL => "http://snapshots.test"
    ) do
      post "/internal/v1/test-hooks/relay/pause", headers: auth
      expect(response).to have_http_status(:success)
      RelayJob.perform_now

      # "A paused relay sends nothing until resumed"
      expect(delivery).not_to have_been_requested
      expect(OutboxSnapshot.find(position).sent_at).to be_nil

      post "/internal/v1/test-hooks/relay/resume", headers: auth
      expect(response).to have_http_status(:success)
      RelayJob.perform_now

      expect(delivery).to have_been_requested.once
      expect(OutboxSnapshot.find(position).sent_at).not_to be_nil
    end
  ensure
    Timekeeping::TestHooks.resume_relay!
  end
end
